final class Router {private Auth$auth;private UserService$users;private EntityService$entities;private WorkflowService$flow;private InventoryService$inventory;public function __construct(Database$db,array$config){$audit=new Audit($db);$this->auth=new Auth($db,$audit,$config['app']);$this->users=new UserService($db,$audit);$this->entities=new EntityService($db,$audit);$this->flow=new WorkflowService($db,$audit,$this->entities);$this->inventory=new InventoryService($db,$audit);}public function run(array$r):mixed{$g=Util::text($r['group']??'');$a=Util::text($r['action']??'');$p=is_array($r['payload']??null)?$r['payload']:$r;$token=$r['token']??$p['token']??null;if($g==='health')return['version'=>'2.0.0','storage'=>'mysql','time'=>Util::now()];if($g==='auth'&&$a==='login')return$this->auth->login($p);if($g==='auth'&&$a==='logout')return$this->auth->logout($token);$u=$this->auth->user($token);return match($g){'auth'=>$this->auth->public($u),'users'=>$this->users->handle($a,$p,$u),'vehicles'=>$this->entities->vehicles($a,$p,$u),'deliveries'=>$this->entities->deliveries($a,$p,$u),'prn'=>$this->flow->prn($a,$p,$u),'prnItems'=>$this->flow->items($a,$p,$u),'pallets'=>$this->flow->pallet($a,$p,$u),'cells'=>$this->inventory->cells($a,$p,$u),'placements'=>$this->inventory->place($a,$p,$u),'search'=>$this->inventory->search($p),'dashboard'=>$this->inventory->dashboard(),default=>throw new ApiException('ROUTE','Неизвестная операция API',404)};}}
